import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

import * as projen from 'projen'
import { Skills } from 'projen-skills'

const outdir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke-'))
const project = new projen.Project({ name: 'smoke', outdir })
const read = (file) => fs.readFileSync(path.join(outdir, file), 'utf8')

// NodePackage installs its dependencies after synthesis.
process.env.PROJEN_DISABLE_POST = '1'
new projen.javascript.NodePackage(project, { packageName: 'smoke' })
new Skills(project, {
  sync: false,
  skills: [
    { source: 'vercel-labs/skills', ref: 'v1.0.0', skills: ['find-skills'] },
  ],
})

project.synth()

assert.equal(
  JSON.parse(read('package.json')).skills[0].skills[0],
  'find-skills',
)
